console.log("聚焦此实体");
const ai_kb_graph_entity = data[0].id;
const graph_tree = view.getCtrl("TREE", "treeexpbar2_tree");
const graph = graph_tree.graph;
// 初始化需要保留的节点和边集合
const keepNodeIds = new Set([ai_kb_graph_entity]);
const keepEdgeIds = new Set();

// 获取当前节点的所有相邻节点（1层邻居）
const layer1Nodes = [];
graph.getEdgeData().forEach(edge => {
    const { source, target, id } = edge;
    if (source === ai_kb_graph_entity) {
        keepNodeIds.add(target);
        layer1Nodes.push(target);
        keepEdgeIds.add(id);
    } else if (target === ai_kb_graph_entity) {
        keepNodeIds.add(source);
        layer1Nodes.push(source);
        keepEdgeIds.add(id);
    }
});

// 获取1层节点的相邻节点（2层邻居）
layer1Nodes.forEach(nodeId => {
    graph.getEdgeData().forEach(edge => {
        const { source, target, id } = edge;
        // 检查是否连接到1层节点
        if (source === nodeId || target === nodeId) {
            const neighbor = source === nodeId ? target : source;
            // 仅添加未在keepNodeIds中的节点（避免重复和回溯）
            if (!keepNodeIds.has(neighbor)) {
                keepNodeIds.add(neighbor);
                keepEdgeIds.add(id);
            }
        }
    });
});

// 设置节点状态：高亮0层、1层、2层节点
graph.setElementState(
    graph.getNodeData().reduce((acc, node) => {
    graph.setElementVisibility(node.id, 'visibility');
        acc[node.id] = keepNodeIds.has(node.id) 
            ? ["highlight"] 
            : ["inactive"];
        return acc;
    }, {})
);

// 设置边状态：高亮0-1层和1-2层的边
graph.setElementState(
    graph.getEdgeData().reduce((acc, edge) => {
        graph.setElementVisibility(edge.id, 'visibility');
        acc[edge.id] = keepEdgeIds.has(edge.id)
            ? ["highlight"]
            : ["inactive"];
        return acc;
    }, {})
);

// 聚焦并缩放
await graph.focusElement(ai_kb_graph_entity);
graph.zoomTo(1.2);

